-- Fixed offer-only probe of an already staged fleet transport, before VAP moves.
-- PLAN/BASE/NONCE/PROBE_NONCE are generated by the reviewed fleet coordinator.
local nx=require("nixio")
local fs=require("nixio.fs")
local sp=require("luci.model.subprocess")
local json=require("luci.json")
local function read(path,limit)
    local f=assert(io.open(path,"rb"));local value=f:read(limit or "*a");assert(f:close())
    if value==nil and limit then return "" end
    return assert(value)
end
local function trim(value) return value:match("^%s*(.-)%s*$") end
local function output(argv)
    local body,code=sp.call_output(argv)
    assert(code==0,"fixed getter failed");return body or ""
end
local function uptime() return assert(tonumber(read("/proc/uptime"):match("^[%d.]+"))) end
local function snapshot()
    return {
        main_addresses=output({"/usr/sbin/ip","addr","show","dev","br-lan"}),
        routes=output({"/usr/sbin/ip","route","show"}),
        private_addresses=output({"/usr/sbin/ip","addr","show","dev","br-iot"}),
        vlan30_ports=output({"/sbin/swconfig","dev","switch1","vlan","30","get","ports"}),
        main_bridge=read("/sys/class/net/br-lan/bridge/bridge_id")}
end
assert(nx.getuid()==0,"root required")
assert(trim(read("/tmp/sync-cached-DEV_ID"))==PLAN.device_id,"wrong device")
assert(trim(read("/proc/sys/kernel/random/boot_id"))==PLAN.boot_id,"wrong boot")
local state=json.decode(read(BASE.."/state.json"))
assert(state.nonce==NONCE and state.phase=="staged","transport not staged")
assert(read("/tmp/deco-iot-trial-active/owner")==NONCE,"reservation changed")
assert(not fs.stat(BASE.."/abort") and not fs.stat(BASE.."/done.json"),"trial no longer active")
assert(state.deadline==PLAN.deadline and state.deadline-uptime()>=30,"insufficient shared time")
local main=read("/sys/class/net/br-lan/bridge/bridge_id")
for _,name in ipairs({"ath08","ath18"}) do
    assert(read("/sys/class/net/"..name.."/master/bridge/bridge_id")==main,"VAP moved before transport proof")
end
assert(read("/sys/class/net/eth1.30/master/bridge/bridge_id")==read("/sys/class/net/br-iot/bridge/bridge_id"),"VLAN master changed")
assert(type(PROBE_NONCE)=="string" and #PROBE_NONCE==32 and PROBE_NONCE:match("^%x+$"),"bad probe owner")
local before=snapshot()
assert(trim(before.vlan30_ports):gsub("%s+"," ")==PLAN.tagged_ports,"tagged membership changed")
assert(not before.private_addresses:match("\n%s+inet[6]?%s"),"private bridge has an address")
local pidpath=BASE.."/offer-"..PROBE_NONCE..".pid"
local logpath=BASE.."/offer-"..PROBE_NONCE..".log"
assert(not fs.stat(pidpath) and not fs.stat(logpath),"probe path exists")
-- Exact vendor -Q returns at OFFER before lease hooks/smartip. Ten tries cannot
-- exhaust before the eight-second KILL; no DHCPREQUEST/ACK lease is requested.
local argv={"/bin/busybox","timeout","-t","8","-s","KILL",
    "/bin/busybox","udhcpc","-f","-n","-Q","-m","normal","-i","br-iot",
    "-s","/bin/true","-p",pidpath,"-t","10","-T","2"}
local function identity(pid)
    local ok,text=pcall(read,"/proc/"..tostring(pid).."/stat")
    if not ok then return nil end
    local rest=text:match("^%d+ %(.+%) (.*)$");if not rest then return nil end
    local fields={};for item in rest:gmatch("%S+") do fields[#fields+1]=item end
    return {start=tonumber(fields[20]),state=fields[1]}
end
local child,file,observed
local hard_deadline=uptime()+10
local function stop()
    if not child or observed then return end
    local current=identity(child.pid)
    -- comm may change at exec; PID/start remains the owned child's identity.
    if current and child.start and current.start==child.start and current.state~="Z" then
        nx.kill(child.pid,9)
    end
end
local function reap(deadline)
    while true do
        local pid,reason,code=nx.waitpid(child.pid,"nohang")
        if pid and pid>0 then observed={reason=reason,code=code};return true end
        local remaining=deadline-uptime()
        if remaining<=0 then return false end
        nx.nanosleep(0,math.floor(math.min(0.05,remaining)*1000000000))
    end
end
local ok=pcall(function()
    -- This exact two-argument nixio open plus chmod form is proven on-device.
    -- sp.call_output captures stdout only; udhcpc logs its OFFER exit to stderr.
    file=assert(nx.open(logpath,"w"),"log open failed")
    assert(fs.chmod(logpath,"rw-------"),"log permission failed")
    local pid=assert(nx.fork(),"client fork failed")
    if pid==0 then
        pcall(function()
            local null=assert(nx.open("/dev/null","r"))
            assert(nx.dup(null,nx.stdin));assert(nx.dup(file,nx.stdout));assert(nx.dup(file,nx.stderr))
            null:close();file:close()
            nx.execp(unpack(argv))
        end)
        os.exit(127)
    end
    child={pid=pid}
    local own=identity(pid);child.start=own and own.start
    assert(child.start,"client identity unavailable")
    assert(file:close(),"parent log close failed");file=nil
    if not reap(hard_deadline-1) then stop() end
end)
-- Cleanup remains bounded on every parent-side error; never use blocking waitpid.
if file then pcall(file.close,file) end
local cleaned=pcall(function()
    if child and not observed then stop();assert(reap(hard_deadline),"client cleanup timed out") end
end)
assert(ok and cleaned and observed,"fixed offer observation failed")
local code=observed.reason=="exited" and observed.code or
    (observed.reason=="signaled" and 128+observed.code or -1)
local log=read(logpath,2049)
local after=snapshot()
local unchanged=true
for key,value in pairs(before) do if after[key]~=value then unchanged=false end end
return {kind="deco_fleet_offer_probe",nonce=NONCE,probe_nonce=PROBE_NONCE,
    device_id=trim(read("/tmp/sync-cached-DEV_ID")),boot_id=trim(read("/proc/sys/kernel/random/boot_id")),
    uid=nx.getuid(),offer_only=true,lease_requested=false,
    interface_addresses_routes_unchanged=unchanged,client_exit_code=code,
    client_log=log:sub(1,2048),client_log_truncated=#log>2048,
    pcap_collected=false,remaining_seconds=state.deadline-uptime()}
